mapper.select:
select c.id, c.document_id, c.chunk_no, c.section_path, c.page_no, c.content, c.normalized,
       c.keywords, d.title, d.protocol_code, d.protocol_version, d.source_document_id
from ai_chunk c join ai_document d on d.id = c.document_id
where d.status = 'PUBLISHED'
and d.protocol_code = #{protocolCode}
and d.protocol_version = #{protocolVersion}
and 
    c.normalized like concat('%', #{keyword}, '%')

limit #{limit}

select id, source, source_document_id, protocol_code, protocol_version, title, content_hash, status,
    chunk_count, index_version, updated_at from ai_document where source = #{source} and source_document_id =
    #{sourceDocumentId}
